  "6": "\n        <div class=\"p-5 flex flex-col justify-between h-full bg-[#0d120f]\">\n          <div>\n            <h3 class=\"text-base font-black text-white\">Document Expiry Watchdog</h3>\n            <p class=\"text-[10px] text-slate-400\">Table: <code>driver_documents.expires_at</code>.</p>\n            <div class=\"mt-4 p-4 bg-amber-500/10 border border-amber-500/30 rounded-2xl text-xs space-y-2\">\n              <h4 class=\"font-bold text-amber-400\">Attention Pilot Suresh:</h4>\n              <p class=\"text-slate-300\">Your Police Verification Certificate is expiring on <strong>31 Dec 2026</strong>. Please upload renewal copy before cut-off to avoid duty suspension.</p>\n            </div>\n            <button class=\"w-full mt-4 py-3 bg-slate-900 border border-slate-700 rounded-xl text-xs font-bold text-white\">\n              Upload Updated Document\n            </button>\n          </div>\n          <button onclick=\"selectScreen(5)\" class=\"w-full py-3 rounded-xl bg-slate-800 text-white font-bold text-xs\">\n            Back to Document Vault\n          </button>\n        </div>\n        ",
